template:
fn first_char(
    s: &str,
) -> Result<char, &'static str> {
    let ch = s
        .chars()
        .next()
        ⟦slot1⟧
        ⟦slot2⟧;
    Ok(ch)
}

fn main() {
    let _ = first_char("a");
}

tests:
#[test]
fn test_char() {
    assert_eq!(first_char("abc"), Ok('a'));
    assert_eq!(first_char(""), Err("empty"));
}
